const btn = document.querySelector('button');
const imgbox = document.getElementById('imgBox');
const qrImage = document.getElementById('Qr-Image');
const input = document.getElementById('Qr-text');
const loadelement = document.createElement('p');

imgbox.append(loadelement);
loadelement.hidden = true;

const getQR = async () => {
    const inputValue = input.value.trim();

    if (inputValue.length > 0) {
        loadelement.hidden = false;
        qrImage.src = '';
        qrImage.style.display = 'none';
        loadelement.classList.remove('invalid-input');
        loadelement.innerHTML = 'Loading ...';

        const apiUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(inputValue)}`;

        try {
            const response = await fetch(apiUrl);

            if (!response.ok) {
                throw new Error('Network response was not ok');
            }

            // For this specific API, the URL itself is the source
            qrImage.src = response.url;

            // Wait for image to actually load before hiding loader
            qrImage.onload = () => {
                loadelement.hidden = true;
                qrImage.style.display = 'block';
            };

            qrImage.onerror = () => {
                throw new Error('Image failed to load');
            };

        } catch (error) {
            console.error('Fetch error:', error);
            loadelement.classList.add('invalid-input');
            loadelement.innerHTML = 'Error fetching QR Code!';
            loadelement.hidden = false;
        }
    } else {
        qrImage.src = '';
        qrImage.style.display = 'none';
        loadelement.hidden = false;
        loadelement.classList.add('invalid-input');
        loadelement.innerHTML = 'Invalid Input !';
    }
};

btn.addEventListener('click', getQR);
```

